using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

var tools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about "
    + "the given topic. Use the take_note tool to record key findings as you go. "
    + "After gathering enough information (at least 3 searches), provide a final summary "
    + "of your research notes.",
    [AIFunctionFactory.Create(tools.WebSearch), AIFunctionFactory.Create(tools.TakeNote)]);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and summarize your findings: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Notes ===");
foreach (var note in tools.Notes)
{
    Console.WriteLine($"• {note}");
}

/// <summary>
/// Tools available to the research agent for searching the web and taking notes.
/// </summary>
sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    private readonly HttpClient _httpClient = new();

    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public async Task<string> WebSearch([Description("The search query")] string query)
    {
        Console.WriteLine($"  [Searching: \"{query}\"]");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            using var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var response = await _httpClient.SendAsync(request);
            var html = await response.Content.ReadAsStringAsync();

            // Extract text snippets from result blocks
            var snippets = ExtractSnippets(html);
            return snippets.Length > 0
                ? snippets
                : $"Search completed for '{query}' but no structured snippets were extracted. "
                  + "Try a more specific query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }

    [Description("Record a research note. Use this to save key findings during research.")]
    public string TakeNote([Description("The note content to record")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Note taken: \"{Truncate(note, 60)}\"]");
        return $"Note recorded ({_notes.Count} total notes).";
    }

    private static string ExtractSnippets(string html)
    {
        var results = new List<string>();
        var searchStr = "class=\"result__snippet";

        var index = 0;
        while (results.Count < 5 && (index = html.IndexOf(searchStr, index, StringComparison.Ordinal)) >= 0)
        {
            var start = html.IndexOf('>', index) + 1;
            var end = html.IndexOf('<', start);
            if (start > 0 && end > start)
            {
                var snippet = System.Net.WebUtility.HtmlDecode(html[start..end]).Trim();
                if (snippet.Length > 20)
                {
                    results.Add(snippet);
                }
            }
            index = end > 0 ? end : index + 1;
        }

        return string.Join("\n\n", results);
    }

    private static string Truncate(string value, int maxLength) =>
        value.Length <= maxLength ? value : value[..maxLength] + "...";
}

