        + "After gathering enough information, provide a final comprehensive summary.",
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: [AIFunctionFactory.Create(tools.WebSearch), AIFunctionFactory.Create(tools.TakeNote)]);

